# Bám sách: trang 104–105 + đáp án + Mini dictionary unit 50. Không chép nguyên văn.
theory = (
 H("A", "Driving", "Lái xe")
 + P("Freddie tells the story of a car journey that went wrong from start to finish.", "Freddie kể về một chuyến đi bằng ô tô gặp trục trặc từ đầu đến cuối.")
 + T([
    ("<b>cut in</b> (on sb)", "Five minutes onto the motorway, another driver suddenly moved in front of him without leaving enough space, so he had to brake hard.", "Mới đi năm phút trên đường cao tốc, một xe khác bất ngờ chen vào trước mặt anh, không chừa đủ khoảng cách, nên anh phải phanh gấp."),
    ("<b>pull out</b>", "He moved into the faster part of the road to overtake a lorry, and the engine died.", "Anh lách sang làn nhanh hơn để vượt một xe tải thì máy chết."),
    ("<b>change down</b>", "After the engine restarted, he put the car into a lower gear and went back to the slow lane.", "Máy nổ lại, anh về số thấp hơn và quay lại làn chậm."),
    ("<b>flag down</b>", "Because he was so slow, a police officer waved at him to stop and warned him about a worn tyre.", "Vì anh đi quá chậm, một cảnh sát vẫy xe anh dừng lại và nhắc anh về chiếc lốp mòn."),
    ("<b>pick up speed</b>", "He started again and began to go faster …", "Anh khởi hành lại và bắt đầu tăng tốc…"),
    ("<b>blow out</b>", "… then the worn tyre suddenly burst, costing another half hour.", "… rồi chiếc lốp mòn bất ngờ nổ, mất thêm nửa tiếng."),
    ("<b>pick up</b> sb", "He let a hitchhiker get into the car because he felt sorry for him.", "Anh cho một người đi nhờ xe lên vì thấy thương."),
    ("<b>branch off</b>", "They turned off the motorway onto a smaller road.", "Họ rẽ khỏi đường cao tốc sang một con đường nhỏ hơn."),
    ("<b>block in</b>", "Outside the café, someone had parked so close that he could not drive away – and the hitchhiker had taken his waterproof jacket.", "Ở ngoài quán cà phê, ai đó đỗ xe sát đến mức anh không lái ra được – và người đi nhờ đã lấy mất áo khoác chống nước của anh."),
 ])
 + H("B", "Other phrasal verbs connected with transport", "Các phrasal verb khác về giao thông")
 + T([
    ("<b>stack up</b>", "Five planes flew over an airport at different heights, waiting for permission to land.", "Năm máy bay bay vòng ở các độ cao khác nhau trên sân bay, chờ được phép hạ cánh."),
    ("<b>stow away</b> / <b>stowaway</b>", "Two young men hid on a ferry to enter a country illegally; police had already arrested over 20 people doing this at the port.", "Hai thanh niên trốn trên phà để nhập cảnh trái phép; cảnh sát đã bắt hơn 20 người trốn vé như vậy ở cảng."),
    ("<b>be cast away</b>", "In a TV programme celebrities pretend to be alone on a desert island after swimming from a sinking ship.", "Trong một chương trình truyền hình, người nổi tiếng giả vờ bị dạt lên đảo hoang sau khi bơi khỏi một con tàu đắm."),
    ("<b>knock over</b>", "A cyclist hit a woman and she broke her arm.", "Một người đi xe đạp đâm vào một phụ nữ khiến cô gãy tay."),
    ("<b>pull over</b>", "A police car ordered the driver to stop at the side of the road, and the car was searched.", "Xe cảnh sát buộc xe dừng vào lề đường, rồi khám xét xe."),
    ("<b>rev up</b>", "At slow traffic lights, impatient drivers made their engines run faster while standing still.", "Ở cột đèn đổi chậm, những tài xế sốt ruột rồ máy trong lúc xe đứng yên."),
 ])
 + NOTE("<b>The author’s answer to ‘Over to you’</b> uses several of these verbs in one story: a driver who <i>pulled out</i> to overtake and <i>cut in</i> dangerously was finally <i>flagged down</i> by a policeman.",
        "<b>Bài viết mẫu của tác giả (phần Over to you)</b> dùng nhiều động từ này trong một câu chuyện: một tài xế cứ <i>lách ra</i> để vượt rồi <i>chen vào</i> nguy hiểm, cuối cùng bị cảnh sát <i>vẫy dừng xe</i>.")
)
